package service;
import java.io.IOException;import java.nio.file.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
import model.Account;import repository.Repository;import util.Validator;import exception.*;
public class BankService {private final Repository<Account> repository=new Repository<>();private final ConcurrentHashMap<String,Account> shared=new ConcurrentHashMap<>();private final Validator validator=new Validator();private final Path data=Path.of("data"),logs=data.resolve("logs"),state=data.resolve("accounts.dat");private int nextNumber=1;public BankService()throws Exception{for(Account a:StatePersister.load(state)){repository.save(a);shared.put(a.getAccountNumber(),a);try{nextNumber=Math.max(nextNumber,Integer.parseInt(a.getAccountNumber().substring(2))+1);}catch(NumberFormatException ignored){}}}public Account openAccount(String name,long opening)throws BankException{if(name==null||name.isBlank())throw new BankException("Owner name cannot be empty.");if(opening<0)throw new InvalidAmountException();Account a=new Account(String.format("AC%04d",nextNumber++),name,opening);repository.save(a);shared.put(a.getAccountNumber(),a);saveState();return a;}private Account find(String id)throws AccountNotFoundException{Account a=shared.get(id);if(a==null)throw new AccountNotFoundException(id);return a;}public void deposit(String id,long amount)throws BankException,IOException{Account a=find(id);a.deposit(amount);TransactionLog.append(logs.resolve("transactions.log"),"DEPOSIT "+id+" "+amount);saveState();}public void withdraw(String id,long amount)throws BankException,IOException{Account a=find(id);a.withdraw(amount);TransactionLog.append(logs.resolve("transactions.log"),"WITHDRAW "+id+" "+amount);saveState();}public void transfer(String fromId,String toId,long amount)throws BankException,IOException{Account from=find(fromId),to=find(toId);if(amount<=0)throw new InvalidAmountException();Account first=fromId.compareTo(toId)<0?from:to,second=first==from?to:from;synchronized(first){synchronized(second){if(from.getBalance()<amount)throw new InsufficientFundsException(amount-from.getBalance());from.withdraw(amount);to.deposit(amount);}}TransactionLog.append(logs.resolve("transactions.log"),"WITHDRAW "+fromId+" "+amount);TransactionLog.append(logs.resolve("transactions.log"),"DEPOSIT "+toId+" "+amount);saveState();}public String statement(String id)throws BankException{return find(id).toString();}public List<Account> listAccounts(){List<Account> a=repository.findAll();a.sort(Comparator.comparingLong(Account::getBalance).reversed());return a;}public String report()throws IOException{return new ReportGenerator().generate(logs,data.resolve("report.txt"));}public boolean isValidMobile(String s){return validator.isValidMobile(s);}public void runBatchDeposit(String id,long amount,int count)throws BankException,InterruptedException{if(amount<=0||count<1)throw new IllegalArgumentException("Amount and number of deposits must be positive.");Account a=find(id);TransactionProcessor p=new TransactionProcessor();for(int i=0;i<count;i++)p.submit(()->{try{a.deposit(amount);TransactionLog.append(logs.resolve("transactions.log"),"DEPOSIT "+id+" "+amount);}catch(InvalidAmountException|IOException e){throw new IllegalStateException(e);}});p.stop();saveState();}public void saveState(){try{StatePersister.save(repository.findAll().toArray(Account[]::new),state);}catch(IOException e){System.out.println("Warning: could not save accounts: "+e.getMessage());}}public void close(){saveState();}}
